-- The value-editor element code module and one element class for each value editor
-- in devdoc 2026102701 §1.3.9 (OpenSpec wpi-value-editor-elements; contract in
-- KnowledgeStore doc-repo/code_modules/interpreter-value-editor.md). Each class fixes
-- the editor it draws; the five editors without code are drafts.
-- +goose Up
-- +goose StatementBegin
INSERT INTO kb.code_modules (code_module_id, module_name, description, module_type, module_doc, notes, creator) VALUES
    ('value-editor', 'Value Editor',
     'Draws one value editor, such as a colour picker or a data-source editor, bound to an input-doc field; each class fixes which editor.',
     'element', 'interpreter-value-editor.md',
     'One module for every value-editor class. Draft classes name editors that have no code yet.',
     'migration:wpi-value-editor-elements')
ON CONFLICT (code_module_id) DO NOTHING;
-- +goose StatementEnd

